    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int idx = s[i - 1] - 'a';

        // 删除第 i 个字符
        dp[i] = dp[i - 1] + 1;

        // 保留第 i 个字符，尝试与前面最近的相同字母配对
        if (last_pos[idx] != -1) {
            int j = last_pos[idx];
            dp[i] = min(dp[i], dp[j - 1] + i - j - 1);
        }

        last_pos[idx] = i;
    }

    cout << dp[n] << "\n";
    return 0;
}
